-- ============================================================================

CREATE OR REPLACE FUNCTION erb_build_parameters()
RETURNS JSONB AS $$
  SELECT '{"erbBlankLogic":"coerce","erbDateDiff":"calendar","erbDateTimeText":"iso8601","erbTimezone":"UTC","erbWholeNumber":"by-field-type"}'::jsonb;
